        <Workspace
          data={wsData}
          onChange={setWsData}
          renderPanel={renderPanel}
          aria-label="Component creator workspace"
        />
      </div>

      {/* Nav bar: Component tabs */}
      <div className={`shrink-0 overflow-x-auto ${styles.navBar}`}>
        <TabList
          data={componentNavData}
