          <span className={ax({ surface: 'action', controlSize: 'sm', tone: 'warning', textStyle: 'caption' })}>Status: Pending</span>
          <span className={ax({ surface: 'action', controlSize: 'sm', tone: 'success', textStyle: 'caption' })}>Tag: New</span>
