        {['Overview', 'Billing', 'Team'].map((t, i) => (
          <div key={t} className={ax({ surface: 'ghost', controlSize: 'sm', text: i === 0 ? 'primary' : 'muted' })} role="tab" aria-selected={i === 0}>
